practicums.solution:
#include <iostream>
#include <iomanip>
using namespace std;

int main() {
    double price, discount, tax;
    int count;
    cin >> price >> count >> discount >> tax;
    if (price < 0 || count < 0 || discount < 0 || tax < 0) {
        cout << "Некорректные данные\n";
        return 0;
    }
    double subtotal = price * count;
    double discountSum = subtotal * discount / 100.0;
    double afterDiscount = subtotal - discountSum;
    double taxSum = afterDiscount * tax / 100.0;
    double total = afterDiscount + taxSum;
    cout << fixed << setprecision(2)
         << "Сумма: " << subtotal << '\n'
         << "Скидка: " << discountSum << '\n'
         << "Налог: " << taxSum << '\n'
         << "Итого: " << total << '\n';
}

