    Employee people[3]={{101,"Анна",60000},{205,"Иван",72000},{310,"Олег",68000}};
    double sum=0;
    for (int i=0;i<3;++i){
        cout<<people[i].id<<" "<<people[i].name<<" "<<people[i].salary<<'\n';
        sum+=people[i].salary;
    }
    cout<<"Средний оклад: "<<sum/3<<'\n';
