practicums.solution:
#include <iostream>
using namespace std;

int main() {
    int a[8]={14,3,9,1,20,7,11,5};
    for(int pass=0;pass<7;++pass)
        for(int i=0;i<7-pass;++i)
            if(a[i]>a[i+1]){ int t=a[i]; a[i]=a[i+1]; a[i+1]=t; }
    for(int x:a) cout<<x<<' ';
    cout<<'\n';
    int target; cin>>target;
    int left=0,right=7,pos=-1;
    while(left<=right){
        int mid=(left+right)/2;
        if(a[mid]==target){pos=mid;break;}
        if(a[mid]<target) left=mid+1; else right=mid-1;
    }
    cout<<"Позиция: "<<pos<<'\n';
}

