practicums.solution:
#include <iostream>
using namespace std;

class Account {
private:
    double balance;
public:
    Account(double start) : balance(start >= 0 ? start : 0) {}
    bool deposit(double value){ if(value<=0) return false; balance+=value; return true; }
    bool withdraw(double value){ if(value<=0 || value>balance) return false; balance-=value; return true; }
    double getBalance() const { return balance; }
};

int main(){
    Account a(1000);
    a.deposit(250);
    cout << a.withdraw(400) << '\n';
    cout << a.getBalance() << '\n';
}

