#include <iostream>
using namespace std;

double calculateTotal(double price, int count, double discount){
    if(price<0 || count<0 || discount<0 || discount>100) return -1;
    return price*count*(1.0-discount/100.0);
}

int main(){
    double result=calculateTotal(1000,3,10);
    if(result<0) cout<<"Ошибка входных данных\n";
    else cout<<result<<'\n';
    // В GUI обработчик Click только получает значения,
    // вызывает calculateTotal и показывает result.
}
